import java.io.*;import java.util.*;class Result {    private static List<List<Integer>> adj;    private static int[] subtreeSums;    private static int[] nodeData;    private static int totalSum;    private static int minDiff;    public static int cutTheTree(List<Integer> data, List<List<Integer>> edges) {        int n = data.size();        adj = new ArrayList<>(n + 1);        for (int i = 0; i <= n; i++) adj.add(new ArrayList<Integer>());        nodeData = new int[n + 1];        totalSum = 0;        for (int i = 0; i < n; i++) {            nodeData[i + 1] = data.get(i);            totalSum += nodeData[i + 1];        }        for (List<Integer> edge : edges) {            int u = edge.get(0);            int v = edge.get(1);            adj.get(u).add(v);            adj.get(v).add(u);        }        subtreeSums = new int[n + 1];        minDiff = Integer.MAX_VALUE;        dfs(1, -1);        return minDiff;    }    private static int dfs(int u, int p) {        int currentSum = nodeData[u];        for (int v : adj.get(u)) {            if (v != p) {                currentSum += dfs(v, u);            }        }        subtreeSums[u] = currentSum;        if (p != -1) {            int diff = Math.abs(totalSum - 2 * currentSum);            if (diff < minDiff) {                minDiff = diff;            }        }        return currentSum;    }}public class Solution {    public static void main(String[] args) throws IOException {        BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in));        BufferedWriter bufferedWriter = new BufferedWriter(new FileWriter(System.getenv("OUTPUT_PATH")));        int n = Integer.parseInt(bufferedReader.readLine().trim());        String[] dataTemp = bufferedReader.readLine().replaceAll("\\s+$", "").split(" ");        List<Integer> data = new ArrayList<>();        for (int i = 0; i < n; i++) {            data.add(Integer.parseInt(dataTemp[i]));        }        List<List<Integer>> edges = new ArrayList<>();        for (int i = 0; i < n - 1; i++) {            String[] edgesRowTempItems = bufferedReader.readLine().replaceAll("\\s+$", "").split(" ");            List<Integer> edgesRowItems = new ArrayList<>();            edgesRowItems.add(Integer.parseInt(edgesRowTempItems[0]));            edgesRowItems.add(Integer.parseInt(edgesRowTempItems[1]));            edges.add(edgesRowItems);        }        int result = Result.cutTheTree(data, edges);        bufferedWriter.write(String.valueOf(result));        bufferedWriter.newLine();        bufferedReader.close();        bufferedWriter.close();    }}